@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--ink:#121d21;--cream:#f2efe7;--lime:#d8fd57;--orange:#ff7955;--muted:#aab7b2}*{box-sizing:border-box}html,body{height:100%;margin:0;background:#101a20;color:var(--cream);font-family:'DM Sans',sans-serif;overflow:hidden}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:480px;overflow:hidden;background:#a6c58e;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,19,25,.56),transparent 25%,transparent 73%,rgba(8,17,20,.59)),radial-gradient(ellipse at center,transparent 54%,rgba(10,22,25,.19));z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:76px;padding:0 4.2%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.13);background:linear-gradient(180deg,rgba(12,26,32,.48),transparent)}.brand{font-family:'Barlow Condensed',sans-serif;letter-spacing:.07em;font-size:23px;font-weight:900;color:#fff;text-decoration:none;display:flex;align-items:center;gap:12px}.brand-light{font-weight:500;color:#d4dfd8;margin-left:4px}.brand-mark{width:24px;height:24px;position:relative;display:flex;align-items:flex-end;gap:3px;transform:skew(-18deg)}.brand-mark i{display:block;width:5px;background:var(--lime);border-radius:1px}.brand-mark i:nth-child(1){height:11px}.brand-mark i:nth-child(2){height:18px}.brand-mark i:nth-child(3){height:14px}.match-tag{font-size:10px;font-weight:700;letter-spacing:.16em;color:rgba(255,255,255,.78);display:flex;align-items:center;gap:8px}.live-dot{height:6px;width:6px;background:var(--lime);border-radius:50%;box-shadow:0 0 12px var(--lime)}.sound-btn{width:34px;height:34px;border-radius:50%;border:1px solid rgba(255,255,255,.3);background:rgba(13,25,29,.28);cursor:pointer;font-size:18px;line-height:1}.game-hud{position:absolute;z-index:3;left:4.2%;right:4.2%;top:94px;display:grid;grid-template-columns:1fr 156px 1fr;align-items:start;pointer-events:none}.hud-left{display:flex;flex-direction:column;gap:13px}.survivors{height:40px;padding:0 13px;display:flex;align-items:center;gap:8px;background:rgba(15,28,30,.56);backdrop-filter:blur(8px);width:max-content;border:1px solid rgba(255,255,255,.1);font-size:9px;letter-spacing:.1em;color:#dce1dc}.survivors strong{font-size:17px;font-family:'Barlow Condensed';letter-spacing:0;color:white}.survivor-icon{font-size:19px;color:var(--lime)}.survivors>i{height:17px;width:1px;background:rgba(255,255,255,.25);margin:0 6px}.storm-info{display:flex;align-items:center;gap:10px;padding-left:9px}.storm-icon{font-size:23px;color:#d8ff64;text-shadow:0 0 16px #a5e445}.storm-info div{display:flex;flex-direction:column;gap:2px}.storm-info b{font-size:9px;letter-spacing:.15em}.storm-info small{font-size:11px;color:#d9e8d1}.minimap-frame{width:156px;height:156px;border:2px solid rgba(237,245,226,.84);box-shadow:0 4px 20px #18252b66;position:relative;background:#97bd86}.minimap-frame canvas{display:block;width:100%;height:100%}.map-label{position:absolute;bottom:-20px;right:0;font-size:8px;letter-spacing:.15em;color:#fff;text-shadow:0 1px 3px #14271a}.hud-right{display:flex;justify-self:end;flex-direction:column;align-items:flex-end;gap:12px}.weapon-card{width:184px;height:56px;display:flex;align-items:center;gap:10px;padding:6px 9px;background:rgba(15,28,30,.62);border:1px solid rgba(255,255,255,.13);backdrop-filter:blur(8px)}.weapon-symbol{width:35px;height:35px;border:1px solid rgba(218,255,90,.5);color:var(--lime);font-size:25px;display:grid;place-items:center}.weapon-card>div:nth-child(2){display:flex;flex-direction:column;gap:1px}.weapon-card small,.materials small{font-size:7px;letter-spacing:.18em;color:#b5c3bb}.weapon-card b{font-size:10px;letter-spacing:.07em}.weapon-card span{font-size:13px;font-weight:700}.weapon-card span i{font-size:10px;color:#aab7b2;font-style:normal}.reload-hint{margin-left:auto;border:1px solid #ffffff44;padding:4px 6px;font-size:9px}.materials{display:flex;align-items:center;gap:8px;color:var(--lime);font-size:12px}.materials b{color:#fff}.materials small{font-size:8px}.health-wrap{position:fixed;left:50%;bottom:61px;transform:translateX(-50%);width:min(330px,40vw);padding:10px 12px;background:rgba(13,26,30,.62);border:1px solid rgba(255,255,255,.1);backdrop-filter:blur(8px)}.health-label{display:flex;justify-content:space-between;align-items:center;font-size:8px;letter-spacing:.14em;color:#d4e0d9;margin-bottom:7px}.health-label>span:last-child{display:flex;gap:4px;align-items:baseline}.health-label b{font-family:'Barlow Condensed';font-size:15px;color:#fff;margin-left:4px}.health-label i{font-style:normal;font-size:7px;color:#9daaa4;margin-right:5px}.health-track{height:8px;background:#54615c;position:relative;overflow:hidden}.health-bar{height:100%;background:#c9f052;width:100%;transition:width .18s}.shield-bar{position:absolute;right:0;top:0;bottom:0;background:#66d7ed;width:33%;opacity:.9}.crosshair{position:absolute;z-index:2;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);pointer-events:none;opacity:0;transition:opacity .2s}.crosshair i{position:absolute;background:#fff;box-shadow:0 1px 3px #111}.crosshair i:nth-child(1){width:2px;height:5px;left:8px;top:0}.crosshair i:nth-child(2){width:2px;height:5px;left:8px;bottom:0}.crosshair i:nth-child(3){height:2px;width:5px;top:8px;left:0}.crosshair i:nth-child(4){height:2px;width:5px;top:8px;right:0}.overlay{position:absolute;z-index:5;inset:0;background:linear-gradient(90deg,rgba(15,27,31,.96) 0%,rgba(15,27,31,.91) 37%,rgba(15,27,31,.34) 74%,rgba(15,27,31,.14) 100%);display:flex}.intro-copy{position:absolute;left:10%;top:19%;max-width:440px}.eyebrow{display:flex;align-items:center;gap:10px;color:var(--lime);font-size:10px;letter-spacing:.21em;font-weight:800}.eyebrow>span{width:22px;height:2px;background:var(--lime)}h1,h2{font-family:'Barlow Condensed',sans-serif;text-transform:uppercase;line-height:.81;letter-spacing:-.02em;margin:19px 0 16px;font-weight:900;font-size:clamp(72px,9vw,124px);color:#f4f1e8}h1 em,h2 em{font-style:normal;color:var(--lime)}.intro-copy p{font-size:14px;line-height:1.75;color:#b9c3bd;margin:24px 0 27px}.play-button{height:54px;width:208px;display:flex;align-items:center;justify-content:space-between;padding:0 17px;border:none;background:var(--lime);color:#182321;cursor:pointer;font-weight:900;letter-spacing:.13em;font-size:12px;transition:transform .18s,background .18s}.play-button:hover{transform:translateY(-2px);background:#e5ff83}.play-button b{font-size:21px;font-weight:500}.quick-tip{margin-top:19px;color:#9aa8a0;font-size:10px}.quick-tip span{color:var(--lime);margin-right:5px}.intro-side{position:absolute;right:6%;top:15%;width:min(40%,540px)}.island-art{height:min(58vh,470px);min-height:300px;position:relative;overflow:hidden;background:linear-gradient(150deg,#263f40,#547667 45%,#bed081);clip-path:polygon(0 0,100% 0,100% 100%,0 100%)}.island-art:after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(13,28,31,.03),rgba(14,29,30,.21));pointer-events:none}.art-sun{position:absolute;right:19%;top:14%;height:88px;width:88px;border-radius:50%;background:#e1db9d;box-shadow:0 0 55px #eee19c77}.art-moon{position:absolute;color:#f4f0d7;right:38%;top:13%;font-size:13px}.art-mountain{position:absolute;bottom:27%;height:58%;width:100%;clip-path:polygon(0 84%,17% 48%,30% 67%,48% 18%,66% 64%,79% 31%,100% 73%,100% 100%,0 100%)}.art-mountain.back{background:#668071;opacity:.72;transform:translateY(-6%)}.art-mountain.front{background:#354d47;clip-path:polygon(0 73%,15% 47%,31% 68%,52% 28%,71% 67%,84% 39%,100% 77%,100% 100%,0 100%)}.art-island{position:absolute;z-index:1;bottom:21%;left:0;right:0;height:32%;border-radius:50% 50% 0 0/24% 28% 0 0;background:#8cae62;transform:scaleX(1.3)}.art-island:before{content:'';position:absolute;left:15%;right:10%;top:18%;height:48%;border-radius:50%;background:#a9c674;transform:rotate(-4deg)}.art-island i{position:absolute;z-index:1;width:13px;height:30px;background:#274d40;bottom:49%;left:23%;border-radius:60% 0 40% 0;transform:rotate(-12deg)}.art-island i:nth-child(2){left:72%;bottom:54%;height:38px}.art-island i:nth-child(3){left:57%;bottom:51%;height:22px}.art-supply{position:absolute;z-index:2;left:56%;top:47%;color:var(--lime);font-size:27px;filter:drop-shadow(0 2px 6px #15211d)}.art-supply b{font:700 8px 'DM Sans';letter-spacing:.12em;display:block;color:white}.art-person{position:absolute;z-index:2;bottom:21%;left:36%;width:12px;height:33px;background:#18262b;border-radius:8px 8px 2px 2px;box-shadow:0 -8px 0 -2px #e0b69c}.art-person:after{content:'';position:absolute;left:9px;top:11px;width:16px;height:3px;background:#d9ddcc;transform:rotate(-25deg);transform-origin:left}.art-ground{position:absolute;z-index:1;bottom:0;left:-5%;width:110%;height:22%;background:linear-gradient(180deg,#526b4c,#283c37);clip-path:polygon(0 30%,19% 18%,36% 26%,55% 0,77% 21%,100% 12%,100% 100%,0 100%)}.art-coord{position:absolute;z-index:2;left:20px;bottom:17px;font-size:8px;letter-spacing:.17em;color:#d8dfc7}.side-caption{display:flex;align-items:center;gap:13px;margin-top:16px}.side-caption>span{font:700 21px 'Barlow Condensed';color:var(--lime)}.side-caption div{display:flex;flex-direction:column;gap:4px}.side-caption b{font-size:9px;letter-spacing:.13em}.side-caption small{font-size:8px;letter-spacing:.12em;color:#92a19a}.controls-note{position:absolute;left:10%;bottom:7%;display:flex;gap:22px;font-size:8px;letter-spacing:.12em;color:#899790}.controls-note b{color:#e6eee6;font-size:9px;margin-right:5px}.bottom-hint{position:absolute;z-index:3;left:4.2%;right:4.2%;bottom:19px;display:flex;align-items:center;gap:18px;font-size:8px;letter-spacing:.12em;color:#fff;text-shadow:0 1px 3px #1a2a27;opacity:.86;pointer-events:none}.bottom-hint span{white-space:nowrap}.bottom-hint i{font-style:normal;color:#c7d0c8;margin-left:4px}.bottom-hint .hint-right{margin-left:auto;font-size:7px;letter-spacing:.17em;color:#d6e0d8}.hidden{display:none!important}.end-overlay{align-items:center;justify-content:center;background:rgba(13,25,29,.78);backdrop-filter:blur(5px)}.end-card{text-align:center;width:min(380px,90vw);padding:33px 40px;background:rgba(20,35,38,.85);border:1px solid #ffffff21;box-shadow:0 20px 70px #0006}.end-card .eyebrow{justify-content:center}.end-emblem{font-size:34px;color:var(--lime);margin-top:20px;text-shadow:0 0 30px #d8fd5777}.end-card h2{font-size:65px;margin:12px 0;color:#f4f1e8}.end-card p{color:#aab7b2;font-size:12px}.match-stats{display:flex;justify-content:center;gap:34px;margin:22px 0}.match-stats div{display:flex;flex-direction:column;gap:3px}.match-stats b{font:700 26px 'Barlow Condensed';color:var(--lime)}.match-stats small{font-size:7px;letter-spacing:.16em;color:#aab7b2}.end-card .play-button{margin:auto}.toast{position:absolute;z-index:4;left:50%;top:26%;transform:translate(-50%,-10px);padding:9px 16px;background:rgba(14,26,29,.8);border:1px solid #d8fd5780;color:#e8f3d9;font-size:10px;letter-spacing:.1em;opacity:0;transition:.22s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.damage-flash{position:absolute;z-index:2;inset:0;border:0 solid rgba(251,77,64,0);pointer-events:none;transition:border-width .12s,background .15s}.damage-flash.hit{border-width:8px;background:rgba(235,50,45,.11)}.touch-controls{display:none}.minimap-frame,.health-wrap,.game-hud,.bottom-hint{transition:opacity .2s}.paused-ui{display:none}
@media(max-width:760px){.topbar{height:56px;padding:0 17px}.brand{font-size:19px}.match-tag{font-size:8px}.game-hud{top:68px;left:12px;right:12px;grid-template-columns:1fr 88px 1fr}.minimap-frame{width:88px;height:88px}.map-label{font-size:6px;bottom:-14px}.survivors{height:32px;padding:0 8px;gap:5px;font-size:7px}.survivors strong{font-size:14px}.survivor-icon{font-size:15px}.storm-info{gap:7px;padding-left:4px}.storm-info b{font-size:7px}.storm-info small{font-size:9px}.storm-icon{font-size:18px}.weapon-card{width:124px;height:43px;gap:6px;padding:4px}.weapon-symbol{width:27px;height:27px;font-size:20px}.weapon-card small{font-size:6px}.weapon-card b{font-size:8px}.weapon-card span{font-size:10px}.reload-hint{font-size:7px;padding:3px}.materials{gap:4px;font-size:10px}.materials small{font-size:6px}.health-wrap{bottom:76px;width:min(280px,62vw);padding:7px 9px}.health-label{font-size:7px;margin-bottom:5px}.health-label b{font-size:13px}.health-track{height:6px}.bottom-hint{display:none}.intro-overlay{background:linear-gradient(90deg,rgba(15,27,31,.97),rgba(15,27,31,.83) 58%,rgba(15,27,31,.54))}.intro-copy{left:8%;top:17%;max-width:85%}h1{font-size:clamp(72px,16vw,112px)}.intro-copy p{font-size:12px}.intro-side{right:0;top:auto;bottom:0;width:70%;opacity:.56}.island-art{height:38vh;min-height:220px}.side-caption{display:none}.controls-note{left:8%;bottom:6%;display:grid;grid-template-columns:1fr 1fr;gap:9px}.controls-note span{font-size:7px}.controls-note b{font-size:8px}.quick-tip{font-size:9px}.play-button{height:48px;width:180px}.touch-controls{display:none;position:absolute;z-index:4;inset:auto 0 0;height:190px;pointer-events:none}.touch-controls.active{display:block}.stick-zone{position:absolute;left:25px;bottom:25px;width:120px;height:120px;pointer-events:auto;touch-action:none}.stick-base{position:absolute;inset:8px;border-radius:50%;background:#172a2c6e;border:1px solid #ffffff55;display:grid;place-items:center}.stick-base:after{content:'';width:5px;height:5px;border-radius:50%;background:#ffffff80}.stick-base i{position:absolute;width:44px;height:44px;border-radius:50%;background:#d8fd57a1;border:1px solid #edffb7;left:50%;top:50%;transform:translate(-50%,-50%);box-shadow:0 2px 10px #0005}.touch-actions{position:absolute;right:25px;bottom:30px;display:flex;gap:12px;align-items:flex-end;pointer-events:auto}.touch-actions button{width:62px;height:62px;border-radius:50%;border:1px solid #fff9;background:#152727ab;font-size:9px;font-weight:800;letter-spacing:.1em;touch-action:none}.touch-actions #touch-fire{width:76px;height:76px;background:#d8fd57d9;color:#162322;border:0}.crosshair{display:none}.toast{top:34%}}
@media(max-height:650px) and (min-width:761px){.intro-copy{top:16%}h1{font-size:clamp(66px,8vw,95px)}.intro-copy p{margin:17px 0}.intro-side{top:12%}.island-art{height:54vh;min-height:260px}.controls-note{bottom:4%}.health-wrap{bottom:47px}}

(()=>{
'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),mini=document.querySelector('#minimap'),mctx=mini.getContext('2d');
const ui={intro:document.querySelector('#intro-overlay'),end:document.querySelector('#end-overlay'),play:document.querySelector('#play-button'),again:document.querySelector('#again-button'),hud:document.querySelector('#game-hud'),cross:document.querySelector('#crosshair'),alive:document.querySelector('#alive-count'),elims:document.querySelector('#elims-count'),storm:document.querySelector('#storm-label'),timer:document.querySelector('#storm-timer'),hp:document.querySelector('#health-value'),shield:document.querySelector('#shield-value'),hpbar:document.querySelector('#health-bar'),shbar:document.querySelector('#shield-bar'),ammo:document.querySelector('#ammo-count'),mats:document.querySelector('#material-count'),toast:document.querySelector('#toast'),flash:document.querySelector('#damage-flash'),touch:document.querySelector('#touch-controls')};
const W=2400,H=1800,TAU=Math.PI*2,rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),dist=(a,b,c,d)=>Math.hypot(a-c,b-d),fmt=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.max(0,Math.floor(t%60))).padStart(2,'0')}`;
let cw=innerWidth,ch=innerHeight,dpr=1,camera={x:W/2,y:H/2},player,bots=[],bullets=[],loot=[],walls=[],props=[],game='menu',last=0,elapsed=0,stormPhase=0,toastTimer=0,mouse={x:cw/2,y:ch/2,down:false},keys={},mobile={x:0,y:0},audioOn=true,audioCtx=null;
function resize(){cw=innerWidth;ch=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=cw*dpr;canvas.height=ch*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function makeMap(){props=[];let seed=841;const rr=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
 // Terrain landmarks and readable paths
 props.push({type:'lake',x:690,y:500,w:210,h:145},{type:'lake',x:1840,y:1210,w:250,h:175},{type:'road',x:1200,y:920,w:2100,h:30});
 for(const a of [[360,360,'NORTH CAMP'],[1200,330,'PINE RIDGE'],[2010,470,'EAST OUTPOST'],[430,1250,'SUNSET YARD'],[1250,1450,'SOUTH FARM'],[2010,1120,'HARBOUR']]){
  const [x,y,name]=a;props.push({type:'town',x,y,name});for(let i=0;i<5;i++){let bx=x+rr()*230-115,by=y+rr()*180-90;props.push({type:'house',x:bx,y:by,w:52+rr()*26,h:42+rr()*24,rot:(Math.floor(rr()*4)*Math.PI/2),color:['#bb8156','#d2b279','#9b7254','#d2d3b6'][Math.floor(rr()*4)]})}
 }
 for(let i=0;i<260;i++){let x=rr()*W,y=rr()*H;if(props.some(p=>(p.type==='lake'||p.type==='house')&&dist(x,y,p.x,p.y)<(p.type==='lake'?p.w*.65:65)))continue;props.push({type:rr()<.78?'tree':'rock',x,y,r:rr()<.78?rand(13,25):rand(9,17),tone:Math.floor(rr()*4)})}
}
function reset(){elapsed=0;stormPhase=0;bullets=[];loot=[];walls=[];player={x:W/2,y:H/2,hp:100,shield:50,maxHp:100,maxShield:100,ammo:24,reserve:96,mag:24,kills:0,materials:30,angle:0,fire:0,reload:0,build:0,dead:false};bots=[];for(let i=0;i<11;i++){let a=rand(0,TAU),r=rand(350,900),x=clamp(player.x+Math.cos(a)*r,80,W-80),y=clamp(player.y+Math.sin(a)*r,80,H-80);bots.push({x,y,hp:100,shield:rand(0,45),angle:0,fire:rand(.4,2),wander:rand(0,TAU),think:rand(0,1.5),speed:rand(72,93),alive:true,color:['#e17b5d','#6488c8','#e3bd54','#b782d1','#52aa88','#db9c53'][i%6],name:['Rook','Juniper','Mako','Scout','Vex','Sol','Moss','Echo','Pip','Ranger','Kite'][i],ammo:24});}
 makeMap();game='playing';ui.intro.classList.add('hidden');ui.end.classList.add('hidden');ui.cross.style.opacity='1';ui.touch.classList.toggle('active',innerWidth<=760);notify('LANDING ZONE: PINE RIDGE');updateHud();last=performance.now();requestAnimationFrame(loop);}
function notify(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.2}
function tone(freq=220,duration=.06,type='square',vol=.025){if(!audioOn)return;try{audioCtx??=new AudioContext();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
function worldMouse(){return{x:mouse.x-cw/2+camera.x,y:mouse.y-ch/2+camera.y}}
function blocked(x,y,r=12){if(x<r||y<r||x>W-r||y>H-r)return true;for(const p of props){if(p.type==='house'&&Math.abs(x-p.x)<p.w*.5+r&&Math.abs(y-p.y)<p.h*.5+r)return true;if(p.type==='lake'&&((x-p.x)**2/(p.w*.5+r)**2+(y-p.y)**2/(p.h*.5+r)**2)<1)return true;}for(const w of walls)if(Math.abs(x-w.x)<w.w/2+r&&Math.abs(y-w.y)<w.h/2+r)return true;return false}
function moveEntity(e,dx,dy,r=12){let nx=e.x+dx;if(!blocked(nx,e.y,r))e.x=nx;let ny=e.y+dy;if(!blocked(e.x,ny,r))e.y=ny}
function circleStorm(){return{r:Math.max(145,1050-elapsed*8.15),x:W/2+Math.sin(elapsed*.025)*100,y:H/2+Math.cos(elapsed*.02)*60}}
function shoot(owner,x,y,angle,isPlayer){let speed=isPlayer?710:530;bullets.push({x:x+Math.cos(angle)*19,y:y+Math.sin(angle)*19,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:isPlayer?1.05:.95,owner,isPlayer,damage:isPlayer?28:12});tone(isPlayer?150:115,.055,'triangle',.015)}
function damage(target,n,source){if(!target.alive&&target!==player)return;let left=n;if(target.shield>0){let s=Math.min(target.shield,left);target.shield-=s;left-=s}target.hp=Math.max(0,target.hp-left);if(target===player){ui.flash.classList.add('hit');setTimeout(()=>ui.flash.classList.remove('hit'),100);tone(90,.09,'sawtooth',.025)}if(target.hp<=0){if(target===player){player.dead=true;finish(false)}else{target.alive=false;if(source===player){player.kills++;let a=rand(0,TAU);loot.push({x:target.x,y:target.y,type:'cache',life:20});notify(`ELIMINATED ${target.name.toUpperCase()}`);tone(520,.16,'sine',.04)}else loot.push({x:target.x,y:target.y,type:'cache',life:20});updateHud()}}}
function fire(){if(game!=='playing'||player.reload>0||player.fire>0)return;if(player.ammo<=0){reload();return}let t=worldMouse();player.angle=Math.atan2(t.y-player.y,t.x-player.x);shoot(player,player.x,player.y,player.angle,true);player.ammo--;player.fire=.14;updateHud()}
function reload(){if(player.reload>0||player.ammo>=player.mag||player.reserve<=0)return;player.reload=1.15;notify('RELOADING');tone(330,.07,'sine',.018)}
function build(){if(game!=='playing'||player.materials<10||player.build>0)return;let a=player.angle, x=player.x+Math.cos(a)*43,y=player.y+Math.sin(a)*43;let horizontal=Math.abs(Math.cos(a))>Math.abs(Math.sin(a));let w=horizontal?68:13,h=horizontal?13:68;if(blocked(x,y,27)){notify('NO ROOM TO BUILD');return}walls.push({x,y,w,h,hp:90,life:38});player.materials-=10;player.build=.35;tone(250,.09,'square',.018);notify('COVER BUILT · −10 MATERIAL')}
function collect(){for(let i=loot.length-1;i>=0;i--){let l=loot[i];if(dist(player.x,player.y,l.x,l.y)<38){if(l.type==='cache'){player.ammo=Math.min(player.mag,player.ammo+8);player.reserve+=24;player.shield=Math.min(100,player.shield+18);player.materials+=10;notify('SUPPLY CACHE · +AMMO +SHIELD +MATERIAL')}else if(l.type==='heal'){player.hp=Math.min(100,player.hp+30);notify('MED KIT · +30 HP')}loot.splice(i,1);tone(660,.1,'sine',.025);updateHud()}}}
function update(dt){if(game!=='playing')return;elapsed+=dt;player.fire=Math.max(0,player.fire-dt);player.build=Math.max(0,player.build-dt);if(player.reload>0){player.reload-=dt;if(player.reload<=0){let n=Math.min(player.mag-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;updateHud();notify('RIFLE READY')}}
 let dx=(keys.KeyD?1:0)-(keys.KeyA?1:0)+mobile.x,dy=(keys.KeyS?1:0)-(keys.KeyW?1:0)+mobile.y,m=Math.hypot(dx,dy);if(m>1){dx/=m;dy/=m}let sprint=keys.ShiftLeft||keys.ShiftRight;let sp=sprint?250:178;moveEntity(player,dx*sp*dt,dy*sp*dt,13);let t=worldMouse();player.angle=Math.atan2(t.y-player.y,t.x-player.x);
 let storm=circleStorm();if(dist(player.x,player.y,storm.x,storm.y)>storm.r){player.stormDamage=(player.stormDamage||0)+dt;if(player.stormDamage>.7){player.stormDamage=0;damage(player,5,null);notify('STORM DAMAGE · GET TO THE SAFE ZONE')}}else player.stormDamage=0;
 for(const b of bots){if(!b.alive)continue;b.fire-=dt;b.think-=dt;let d=dist(b.x,b.y,player.x,player.y),outside=dist(b.x,b.y,storm.x,storm.y)>storm.r-40;let tx=player.x,ty=player.y;if(d>430){if(b.think<=0){b.wander=rand(0,TAU);b.think=rand(1.3,3.8)}tx=b.x+Math.cos(b.wander)*110;ty=b.y+Math.sin(b.wander)*110}else if(d<145){tx=b.x+(b.x-player.x);ty=b.y+(b.y-player.y)}if(outside){tx=storm.x;ty=storm.y}let a=Math.atan2(ty-b.y,tx-b.x);b.angle=Math.atan2(player.y-b.y,player.x-b.x);let pace=(d<430?b.speed*.47:b.speed)*(outside?1.3:1);if(d>90||outside){let ox=b.x,oy=b.y;moveEntity(b,Math.cos(a)*pace*dt,Math.sin(a)*pace*dt,12);if(Math.abs(ox-b.x)+Math.abs(oy-b.y)<.2){b.wander+=rand(1,3);b.think=.2}}if(d<410&&b.fire<=0&&Math.random()<.78){let spread=rand(-.22,.22)+d*.00017;shoot(b,b.x,b.y,b.angle+spread,false);b.fire=rand(.72,1.3)}if(dist(b.x,b.y,storm.x,storm.y)>storm.r){b.storm=(b.storm||0)+dt;if(b.storm>1){damage(b,4,null);b.storm=0}}else b.storm=0;}
 for(let i=bullets.length-1;i>=0;i--){let b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;let hit=false;if(b.isPlayer){for(const bot of bots)if(bot.alive&&bot!==b.owner&&dist(b.x,b.y,bot.x,bot.y)<14){damage(bot,b.damage,player);hit=true;break}}else if(dist(b.x,b.y,player.x,player.y)<14){damage(player,b.damage,b.owner);hit=true}else{for(const bot of bots)if(bot.alive&&bot!==b.owner&&dist(b.x,b.y,bot.x,bot.y)<13){damage(bot,b.damage,b.owner);hit=true;break}}
 if(!hit&&(b.x<0||b.y<0||b.x>W||b.y>H||blocked(b.x,b.y,1)))hit=true;if(hit||b.life<=0)bullets.splice(i,1)}
 for(let i=loot.length-1;i>=0;i--){loot[i].life-=dt;if(loot[i].life<=0)loot.splice(i,1)}for(let i=walls.length-1;i>=0;i--){walls[i].life-=dt;if(walls[i].life<=0)walls.splice(i,1)}collect();camera.x+=(player.x-camera.x)*Math.min(1,dt*6);camera.y+=(player.y-camera.y)*Math.min(1,dt*6);camera.x=clamp(camera.x,cw/2,W-cw/2);camera.y=clamp(camera.y,ch/2,H-ch/2);updateHud();if(bots.filter(b=>b.alive).length===0)finish(true);
}

function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,cw,ch);let ox=cw/2-camera.x,oy=ch/2-camera.y;ctx.save();ctx.translate(ox,oy);ctx.fillStyle='#9bbb7e';ctx.fillRect(0,0,W,H);
 // soft terrain variation, fields, paths and shoreline
 for(let i=0;i<42;i++){let x=(i*617+93)%W,y=(i*379+181)%H;ctx.fillStyle=i%3?'rgba(226,224,153,.08)':'rgba(50,101,63,.07)';ctx.beginPath();ctx.ellipse(x,y,70+i%4*14,28+i%5*7,i*.31,0,TAU);ctx.fill()}
 ctx.fillStyle='#d3c99e';ctx.fillRect(0,904,W,32);ctx.fillStyle='#b8ad84';ctx.fillRect(0,912,W,12);ctx.strokeStyle='#e7d8ac';ctx.lineWidth=2;ctx.setLineDash([16,14]);ctx.beginPath();ctx.moveTo(0,920);ctx.lineTo(W,920);ctx.stroke();ctx.setLineDash([]);
 for(const p of props){if(p.x<camera.x-cw*.7||p.x>camera.x+cw*.7||p.y<camera.y-ch*.7||p.y>camera.y+ch*.7)continue;drawProp(p)}
 // storm zone fills the land beyond the safe circle
 const safe=circleStorm();ctx.save();ctx.fillStyle='rgba(87,106,163,.25)';ctx.beginPath();ctx.rect(0,0,W,H);ctx.arc(safe.x,safe.y,safe.r,0,TAU,true);ctx.fill('evenodd');ctx.restore();ctx.beginPath();ctx.arc(safe.x,safe.y,safe.r,0,TAU);ctx.strokeStyle='rgba(212,247,131,.88)';ctx.lineWidth=5;ctx.setLineDash([11,9]);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(safe.x,safe.y,safe.r-5,0,TAU);ctx.strokeStyle='rgba(255,255,255,.35)';ctx.lineWidth=1;ctx.stroke();
 // points of interest names
 for(const p of props)if(p.type==='town'&&dist(camera.x,camera.y,p.x,p.y)<Math.max(cw,ch)*.7){ctx.font='800 10px DM Sans';ctx.textAlign='center';ctx.fillStyle='rgba(30,57,43,.62)';ctx.fillText(p.name,p.x,p.y-100)}
 for(const w of walls){ctx.fillStyle='#81704d';ctx.fillRect(w.x-w.w/2,w.y-w.h/2,w.w,w.h);ctx.strokeStyle='#dec38b';ctx.lineWidth=2;ctx.strokeRect(w.x-w.w/2,w.y-w.h/2,w.w,w.h);for(let x=w.x-w.w/2+8;x<w.x+w.w/2;x+=14){ctx.beginPath();ctx.moveTo(x,w.y-w.h/2);ctx.lineTo(x,w.y+w.h/2);ctx.strokeStyle='#695b41';ctx.stroke()}}
 for(const l of loot){ctx.save();ctx.translate(l.x,l.y+Math.sin(elapsed*5+l.x)*3);ctx.fillStyle='#13252655';ctx.beginPath();ctx.ellipse(0,9,15,7,0,0,TAU);ctx.fill();ctx.fillStyle='#d8fd57';ctx.shadowColor='#ddff5f';ctx.shadowBlur=15;ctx.fillRect(-9,-12,18,18);ctx.shadowBlur=0;ctx.fillStyle='#28443d';ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.fillText('✦',0,2);ctx.restore()}
 for(const b of bullets){ctx.fillStyle=b.isPlayer?'#f7f1be':'#ff9770';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=10;ctx.beginPath();ctx.arc(b.x,b.y,3,0,TAU);ctx.fill();ctx.shadowBlur=0}
 for(const b of bots)if(b.alive)drawFighter(b,false);if(player)drawFighter(player,true);
 // world edge treatment
 ctx.strokeStyle='#294536';ctx.lineWidth=12;ctx.strokeRect(0,0,W,H);ctx.restore();drawMini();}
function drawProp(p){if(p.type==='lake'){ctx.fillStyle='#759e8c';ctx.beginPath();ctx.ellipse(p.x,p.y,p.w/2+10,p.h/2+10,-.2,0,TAU);ctx.fill();ctx.fillStyle='#69aeb0';ctx.beginPath();ctx.ellipse(p.x,p.y,p.w/2,p.h/2,-.2,0,TAU);ctx.fill();ctx.strokeStyle='#b4c68e';ctx.lineWidth=5;ctx.stroke();for(let i=0;i<6;i++){ctx.strokeStyle='#c2dfc58c';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(p.x-50+i*18,p.y-10,15+i%3*8,3,0,0,TAU);ctx.stroke()}return}if(p.type==='house'){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.fillStyle='#596352';ctx.fillRect(-p.w/2+4,-p.h/2+7,p.w,p.h);ctx.fillStyle=p.color;ctx.fillRect(-p.w/2,-p.h/2,p.w,p.h);ctx.strokeStyle='#795b43';ctx.lineWidth=3;ctx.strokeRect(-p.w/2,-p.h/2,p.w,p.h);ctx.fillStyle='#78593e';ctx.fillRect(-7,-3,14,18);ctx.fillStyle='#bbd6cb';ctx.fillRect(-p.w/2+7,-p.h/2+8,10,9);ctx.fillRect(p.w/2-17,-p.h/2+8,10,9);ctx.fillStyle='#a45d49';ctx.fillRect(-p.w/2-4,-p.h/2-6,p.w+8,8);ctx.restore();return}if(p.type==='tree'){ctx.fillStyle='#3b5940';ctx.beginPath();ctx.ellipse(p.x+3,p.y+5,p.r*1.05,p.r*.7,0,0,TAU);ctx.fill();ctx.fillStyle=['#416c45','#527d4d','#608751','#3f684c'][p.tone];ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,TAU);ctx.fill();ctx.fillStyle='rgba(183,202,120,.27)';ctx.beginPath();ctx.arc(p.x-p.r*.25,p.y-p.r*.32,p.r*.48,0,TAU);ctx.fill();ctx.fillStyle='#30503c';ctx.fillRect(p.x-2,p.y+p.r*.3,4,p.r*.65);return}if(p.type==='rock'){ctx.fillStyle='#7b8471';ctx.beginPath();ctx.ellipse(p.x,p.y,p.r,p.r*.72,-.3,0,TAU);ctx.fill();ctx.fillStyle='#a4a68e';ctx.beginPath();ctx.ellipse(p.x-p.r*.25,p.y-p.r*.15,p.r*.48,p.r*.23,-.3,0,TAU);ctx.fill();return}if(p.type==='town'){ctx.fillStyle='rgba(44,63,45,.16)';ctx.beginPath();ctx.arc(p.x,p.y,5,0,TAU);ctx.fill()}}
function drawFighter(e,isPlayer){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.angle||0);ctx.fillStyle='rgba(25,41,31,.32)';ctx.beginPath();ctx.ellipse(1,7,15,9,0,0,TAU);ctx.fill();ctx.fillStyle=isPlayer?'#293f51':e.color;ctx.beginPath();ctx.ellipse(0,0,13,10,0,0,TAU);ctx.fill();ctx.fillStyle=isPlayer?'#d9e3ce':'#f1d0aa';ctx.beginPath();ctx.arc(4,-1,6,0,TAU);ctx.fill();ctx.fillStyle=isPlayer?'#d9fd57':'#303a3a';ctx.fillRect(3,-9,8,7);ctx.fillStyle='#374341';ctx.fillRect(6,-2,20,4);ctx.fillStyle=isPlayer?'#d8fd57':'#ece7d4';ctx.fillRect(19,-1,6,2);ctx.restore();
 if(!isPlayer){ctx.fillStyle='rgba(24,36,32,.65)';ctx.fillRect(e.x-16,e.y-23,32,4);ctx.fillStyle='#ed6d5f';ctx.fillRect(e.x-16,e.y-23,32*e.hp/100,4);if(e.shield>5){ctx.fillStyle='#76dff2';ctx.fillRect(e.x-16,e.y-27,32*e.shield/100,2)}}}
function drawMini(){if(!mini)return;let w=mini.width,h=mini.height;mctx.clearRect(0,0,w,h);mctx.fillStyle='#8cad72';mctx.fillRect(0,0,w,h);mctx.fillStyle='#c4b887';mctx.fillRect(0,h*.5-1,w,3);for(const p of props){let x=p.x/W*w,y=p.y/H*h;if(p.type==='lake'){mctx.fillStyle='#6eb5b4';mctx.beginPath();mctx.ellipse(x,y,p.w/W*w/2,p.h/H*h/2,0,0,TAU);mctx.fill()}else if(p.type==='house'){mctx.fillStyle='#d6c49c';mctx.fillRect(x-2,y-2,4,4)}}let s=circleStorm();mctx.strokeStyle='#e5ff83';mctx.lineWidth=2;mctx.beginPath();mctx.arc(s.x/W*w,s.y/H*h,s.r/W*w,0,TAU);mctx.stroke();for(const b of bots)if(b.alive){mctx.fillStyle='#fb9877';mctx.fillRect(b.x/W*w-1,b.y/H*h-1,3,3)}mctx.fillStyle='#fff';mctx.beginPath();mctx.arc(player.x/W*w,player.y/H*h,4,0,TAU);mctx.fill();mctx.strokeStyle='#203326';mctx.lineWidth=1;mctx.stroke()}

function updateHud(){if(!player)return;let n=bots.filter(b=>b.alive).length;ui.alive.textContent=String(n+1);ui.elims.textContent=String(player.kills);ui.hp.textContent=Math.ceil(player.hp);ui.shield.textContent=Math.ceil(player.shield);ui.hpbar.style.width=`${player.hp}%`;ui.shbar.style.width=`${player.shield}%`;ui.ammo.innerHTML=`${player.ammo} <i>/ ${player.reserve}</i>`;ui.mats.textContent=player.materials;let left=elapsed<80?80-elapsed:elapsed<150?150-elapsed:0;ui.storm.textContent=elapsed<80?'STORM FORMING':elapsed<150?'STORM CLOSING':'SAFE ZONE';ui.timer.textContent=elapsed<150?fmt(left):'—'}
function finish(win){if(game!=='playing')return;game=win?'won':'lost';ui.cross.style.opacity='0';ui.touch.classList.remove('active');ui.end.classList.remove('hidden');document.querySelector('#end-eyebrow').textContent=win?'ISLAND CLAIMED':'MATCH COMPLETE';document.querySelector('#end-title').innerHTML=win?'ISLAND<br/><em>CLAIMED</em>':'ELIMINATED<br/><em>EARLY</em>';document.querySelector('#end-copy').textContent=win?'You outlasted the entire island.':'The island had other plans. Drop back in?';document.querySelector('#end-emblem').textContent=win?'✦':'×';document.querySelector('#final-elims').textContent=player.kills;document.querySelector('#final-time').textContent=fmt(elapsed);tone(win?680:120,.35,win?'sine':'triangle',.04)}
function loop(now){if(game!=='playing')return;let dt=Math.min(.035,(now-last)/1000||0);last=now;update(dt);draw();if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}requestAnimationFrame(loop)}
function pointerPos(e){let r=canvas.getBoundingClientRect();mouse.x=e.clientX-r.left;mouse.y=e.clientY-r.top}
canvas.addEventListener('pointermove',pointerPos);canvas.addEventListener('pointerdown',e=>{if(e.button===0){pointerPos(e);mouse.down=true;canvas.setPointerCapture?.(e.pointerId);fire()}});addEventListener('pointerup',e=>{if(e.button===0)mouse.down=false});addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyR')reload();if(e.code==='KeyQ')build()});addEventListener('keyup',e=>keys[e.code]=false);
ui.play.addEventListener('click',reset);ui.again.addEventListener('click',reset);document.querySelector('#sound-btn').addEventListener('click',()=>{audioOn=!audioOn;document.querySelector('#sound-icon').textContent=audioOn?'♪':'∅';if(audioOn)tone(440,.08,'sine')});
// Mobile virtual joystick and held fire/build actions.
const zone=document.querySelector('#stick-zone'),knob=document.querySelector('#stick-knob');let stickId=null,stickRect=null;zone.addEventListener('pointerdown',e=>{if(game!=='playing')return;stickId=e.pointerId;zone.setPointerCapture(e.pointerId);stickRect=zone.getBoundingClientRect();stick(e)});zone.addEventListener('pointermove',e=>{if(e.pointerId===stickId)stick(e)});function stick(e){let x=e.clientX-(stickRect.left+stickRect.width/2),y=e.clientY-(stickRect.top+stickRect.height/2),d=Math.hypot(x,y),max=37;if(d>max){x=x/d*max;y=y/d*max}mobile.x=x/max;mobile.y=y/max;knob.style.transform=`translate(calc(-50% + ${x}px),calc(-50% + ${y}px))`}function releaseStick(e){if(e.pointerId!==stickId)return;stickId=null;mobile.x=mobile.y=0;knob.style.transform='translate(-50%,-50%)'}zone.addEventListener('pointerup',releaseStick);zone.addEventListener('pointercancel',releaseStick);
const tf=document.querySelector('#touch-fire');tf.addEventListener('pointerdown',e=>{e.preventDefault();tf.setPointerCapture(e.pointerId);mouse.x=cw/2+140;mouse.y=ch/2;fire();tf.dataset.firing='1'});tf.addEventListener('pointerup',()=>tf.dataset.firing='0');tf.addEventListener('pointercancel',()=>tf.dataset.firing='0');document.querySelector('#touch-build').addEventListener('pointerdown',e=>{e.preventDefault();build()});
function frame(){if(game==='playing'&&tf.dataset.firing==='1')fire();requestAnimationFrame(frame)}requestAnimationFrame(frame);
// Dress the title screen with a quiet island scene before deployment.
makeMap();player={x:W/2,y:H/2,hp:100,shield:50,ammo:24,reserve:96,mag:24,kills:0,materials:30,angle:-.55,alive:true};bots=[];for(let i=0;i<8;i++){let a=i*TAU/8,r=rand(400,820);bots.push({x:W/2+Math.cos(a)*r,y:H/2+Math.sin(a)*r,alive:true,hp:100,shield:0,angle:a,color:'#6685a0',name:'',})}camera.x=W/2;camera.y=H/2;draw();
})();

files.patch:
Index: style.css
===================================================================
--- style.css
+++ style.css
@@ -1,4 +1,4 @@
