const $=s=>document.querySelector(s),ui={intro:$('#intro-overlay'),end:$('#end-overlay'),play:$('#play-button'),again:$('#again-button'),cross:$('#crosshair'),alive:$('#alive-count'),elims:$('#elims-count'),storm:$('#storm-label'),timer:$('#storm-timer'),hp:$('#health-value'),shield:$('#shield-value'),hpbar:$('#health-bar'),shbar:$('#shield-bar'),ammo:$('#ammo-count'),mats:$('#material-count'),toast:$('#toast'),flash:$('#damage-flash'),touch:$('#touch-controls')};
const W=2400,H=1800,TAU=Math.PI*2,rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),dist=(a,b,c,d)=>Math.hypot(a-c,b-d),fmt=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.max(0,Math.floor(t%60))).padStart(2,'0')}`;
let cw=innerWidth,ch=innerHeight,dpr=1,camera={x:W/2,y:H/2},player,bots=[],bullets=[],loot=[],walls=[],props=[],game='menu',last=0,elapsed=0,toastTimer=0,mouse={x:cw/2,y:ch/2,down:false},keys={},mobile={x:0,y:0},audioOn=true,audioCtx=null;
function resize(){cw=innerWidth;ch=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=cw*dpr;canvas.height=ch*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function makeMap(){props=[];let seed=841;const rr=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};props.push({type:'lake',x:690,y:500,w:210,h:145},{type:'lake',x:1840,y:1210,w:250,h:175});for(const [x,y,name] of [[360,360,'NORTH CAMP'],[1200,330,'PINE RIDGE'],[2010,470,'EAST OUTPOST'],[430,1250,'SUNSET YARD'],[1250,1450,'SOUTH FARM'],[2010,1120,'HARBOUR']]){props.push({type:'town',x,y,name});for(let i=0;i<5;i++)props.push({type:'house',x:x+rr()*230-115,y:y+rr()*180-90,w:52+rr()*26,h:42+rr()*24,rot:Math.floor(rr()*4)*Math.PI/2,color:['#bb8156','#d2b279','#9b7254','#d2d3b6'][Math.floor(rr()*4)]})}for(let i=0;i<260;i++){let x=rr()*W,y=rr()*H;if(props.some(p=>(p.type==='lake'||p.type==='house')&&dist(x,y,p.x,p.y)<(p.type==='lake'?p.w*.65:65)))continue;props.push({type:rr()<.78?'tree':'rock',x,y,r:rr()<.78?rand(13,25):rand(9,17),tone:Math.floor(rr()*4)})}}
function reset(){elapsed=0;bullets=[];loot=[];walls=[];player={x:W/2,y:H/2,hp:100,shield:50,ammo:24,reserve:96,mag:24,kills:0,materials:30,angle:0,fire:0,reload:0,build:0,dead:false};bots=[];for(let i=0;i<11;i++){let a=rand(0,TAU),r=rand(350,900);bots.push({x:clamp(player.x+Math.cos(a)*r,80,W-80),y:clamp(player.y+Math.sin(a)*r,80,H-80),hp:100,shield:rand(0,45),angle:0,fire:rand(.4,2),wander:rand(0,TAU),think:rand(0,1.5),speed:rand(72,93),alive:true,color:['#e17b5d','#6488c8','#e3bd54','#b782d1','#52aa88','#db9c53'][i%6],name:['Rook','Juniper','Mako','Scout','Vex','Sol','Moss','Echo','Pip','Ranger','Kite'][i],ammo:24})}makeMap();game='playing';$('#game-shell').classList.remove('menu');ui.intro.classList.add('hidden');ui.end.classList.add('hidden');ui.cross.style.opacity='1';ui.touch.classList.toggle('active',innerWidth<=760);notify('LANDING ZONE: PINE RIDGE');updateHud();last=performance.now();requestAnimationFrame(loop)}
function notify(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.2}
function tone(freq=220,duration=.06,type='square',vol=.025){if(!audioOn)return;try{audioCtx??=new AudioContext();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
function worldMouse(){return{x:mouse.x-cw/2+camera.x,y:mouse.y-ch/2+camera.y}}
function blocked(x,y,r=12){if(x<r||y<r||x>W-r||y>H-r)return true;for(const p of props){if(p.type==='house'&&Math.abs(x-p.x)<p.w*.5+r&&Math.abs(y-p.y)<p.h*.5+r)return true;if(p.type==='lake'&&((x-p.x)**2/(p.w*.5+r)**2+(y-p.y)**2/(p.h*.5+r)**2)<1)return true}for(const w of walls)if(Math.abs(x-w.x)<w.w/2+r&&Math.abs(y-w.y)<w.h/2+r)return true;return false}
function moveEntity(e,dx,dy,r=12){let nx=e.x+dx;if(!blocked(nx,e.y,r))e.x=nx;let ny=e.y+dy;if(!blocked(e.x,ny,r))e.y=ny}
function circleStorm(){return{r:elapsed<80?1050:Math.max(145,1050-(elapsed-80)*10.25),x:W/2+Math.sin(elapsed*.025)*100,y:H/2+Math.cos(elapsed*.02)*60}}
function shoot(owner,x,y,angle,isPlayer){let s=isPlayer?710:530;bullets.push({x:x+Math.cos(angle)*19,y:y+Math.sin(angle)*19,vx:Math.cos(angle)*s,vy:Math.sin(angle)*s,life:isPlayer?1.05:.95,owner,isPlayer,damage:isPlayer?28:12});tone(isPlayer?150:115,.055,'triangle',.015)}
function damage(t,n,source){if(!t.alive&&t!==player)return;let left=n;if(t.shield>0){let s=Math.min(t.shield,left);t.shield-=s;left-=s}t.hp=Math.max(0,t.hp-left);if(t===player){ui.flash.classList.add('hit');setTimeout(()=>ui.flash.classList.remove('hit'),100);tone(90,.09,'sawtooth',.025)}if(t.hp<=0){if(t===player){player.dead=true;finish(false)}else{t.alive=false;if(source===player){player.kills++;loot.push({x:t.x,y:t.y,type:'cache',life:20});notify(`ELIMINATED ${t.name.toUpperCase()}`);tone(520,.16,'sine',.04)}else loot.push({x:t.x,y:t.y,type:'cache',life:20});updateHud()}}}
function fire(){if(game!=='playing'||player.reload>0||player.fire>0)return;if(player.ammo<=0){reload();return}let t=worldMouse();player.angle=Math.atan2(t.y-player.y,t.x-player.x);shoot(player,player.x,player.y,player.angle,true);player.ammo--;player.fire=.14;updateHud()}
function reload(){if(player.reload>0||player.ammo>=player.mag||player.reserve<=0)return;player.reload=1.15;notify('RELOADING');tone(330,.07,'sine',.018)}
function build(){if(game!=='playing'||player.materials<10||player.build>0)return;let a=player.angle,x=player.x+Math.cos(a)*43,y=player.y+Math.sin(a)*43,horizontal=Math.abs(Math.cos(a))>Math.abs(Math.sin(a)),w=horizontal?68:13,h=horizontal?13:68;if(blocked(x,y,27)){notify('NO ROOM TO BUILD');return}walls.push({x,y,w,h,hp:90,life:38});player.materials-=10;player.build=.35;tone(250,.09,'square',.018);notify('COVER BUILT · −10 MATERIAL')}
function collect(){for(let i=loot.length-1;i>=0;i--){let l=loot[i];if(dist(player.x,player.y,l.x,l.y)<38){if(l.type==='cache'){player.ammo=Math.min(player.mag,player.ammo+8);player.reserve+=24;player.shield=Math.min(100,player.shield+18);player.materials+=10;notify('SUPPLY CACHE · +AMMO +SHIELD +MATERIAL')}else{player.hp=Math.min(100,player.hp+30);notify('MED KIT · +30 HP')}loot.splice(i,1);tone(660,.1,'sine',.025);updateHud()}}}

