function update(dt){if(game!=='playing')return;elapsed+=dt;player.fire=Math.max(0,player.fire-dt);player.build=Math.max(0,player.build-dt);if(player.reload>0){player.reload-=dt;if(player.reload<=0){let n=Math.min(player.mag-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;updateHud();notify('RIFLE READY')}}let dx=(keys.KeyD?1:0)-(keys.KeyA?1:0)+mobile.x,dy=(keys.KeyS?1:0)-(keys.KeyW?1:0)+mobile.y,m=Math.hypot(dx,dy);if(m>1){dx/=m;dy/=m}let sp=keys.ShiftLeft||keys.ShiftRight?250:178;moveEntity(player,dx*sp*dt,dy*sp*dt,13);let t=worldMouse();player.angle=Math.atan2(t.y-player.y,t.x-player.x);let storm=circleStorm();if(dist(player.x,player.y,storm.x,storm.y)>storm.r){player.stormDamage=(player.stormDamage||0)+dt;if(player.stormDamage>.7){player.stormDamage=0;damage(player,5,null);notify('STORM DAMAGE · GET TO THE SAFE ZONE')}}else player.stormDamage=0;
 for(const b of bots){if(!b.alive)continue;b.fire-=dt;b.think-=dt;let d=dist(b.x,b.y,player.x,player.y),outside=dist(b.x,b.y,storm.x,storm.y)>storm.r-40,tx=player.x,ty=player.y;if(d>430){if(b.think<=0){b.wander=rand(0,TAU);b.think=rand(1.3,3.8)}tx=b.x+Math.cos(b.wander)*110;ty=b.y+Math.sin(b.wander)*110}else if(d<145){tx=b.x+(b.x-player.x);ty=b.y+(b.y-player.y)}if(outside){tx=storm.x;ty=storm.y}let a=Math.atan2(ty-b.y,tx-b.x);b.angle=Math.atan2(player.y-b.y,player.x-b.x);let pace=(d<430?b.speed*.47:b.speed)*(outside?1.3:1);if(d>90||outside){let ox=b.x,oy=b.y;moveEntity(b,Math.cos(a)*pace*dt,Math.sin(a)*pace*dt,12);if(Math.abs(ox-b.x)+Math.abs(oy-b.y)<.2){b.wander+=rand(1,3);b.think=.2}}if(d<410&&b.fire<=0&&Math.random()<.78){shoot(b,b.x,b.y,b.angle+rand(-.22,.22)+d*.00017,false);b.fire=rand(.72,1.3)}if(dist(b.x,b.y,storm.x,storm.y)>storm.r){b.storm=(b.storm||0)+dt;if(b.storm>1){damage(b,4,null);b.storm=0}}else b.storm=0}
 for(let i=bullets.length-1;i>=0;i--){let b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;let hit=false;if(b.isPlayer){for(const bot of bots)if(bot.alive&&dist(b.x,b.y,bot.x,bot.y)<14){damage(bot,b.damage,player);hit=true;break}}else if(dist(b.x,b.y,player.x,player.y)<14){damage(player,b.damage,b.owner);hit=true}else{for(const bot of bots)if(bot.alive&&bot!==b.owner&&dist(b.x,b.y,bot.x,bot.y)<13){damage(bot,b.damage,b.owner);hit=true;break}}if(!hit&&(b.x<0||b.y<0||b.x>W||b.y>H||blocked(b.x,b.y,1)))hit=true;if(hit||b.life<=0)bullets.splice(i,1)}for(let i=loot.length-1;i>=0;i--){loot[i].life-=dt;if(loot[i].life<=0)loot.splice(i,1)}for(let i=walls.length-1;i>=0;i--){walls[i].life-=dt;if(walls[i].life<=0)walls.splice(i,1)}collect();camera.x+=(player.x-camera.x)*Math.min(1,dt*6);camera.y+=(player.y-camera.y)*Math.min(1,dt*6);camera.x=clamp(camera.x,cw/2,W-cw/2);camera.y=clamp(camera.y,ch/2,H-ch/2);updateHud();if(!bots.some(b=>b.alive))finish(true)}

